#include <iostream>
using namespace th01_native;
static void require(bool v,const char* why){if(!v)throw std::runtime_error(why);}
int main(int argc,char** argv){try{
 if(argc!=2)throw std::invalid_argument("Usage: sariel_session_test ASSET_DIR");bool checking_ending=false;unsigned ending_fades=0;unsigned polls=0;SessionHost host{[&](){if(polls>1000)throw std::runtime_error("Menu stalled");InputKeys k;k.enter=(polls++%2)==1;return k;},[&](const Framebuffer& fb,unsigned n){if(checking_ending && n==6){++ending_fades;require(fb.pixel(0,0,0)==0,"Ending outside centered picture must not retain boss background");}}};auto profile=std::filesystem::absolute(argv[0]).parent_path()/"sariel-session-profile";StageSession session(argv[1],host,1,20,profile,ROUTE_MAKAI);require(session.state()==SessionState::playing && session.sariel_state().hp==18 && session.sariel_state().phase==1 && stage_timer==6000,"Live Makai stage20 starts original Sariel HP/phase/timer");auto audio=session.take_audio_commands();bool first_music=false;for(auto a:audio)first_music|=a.operation=="bgm_load" && a.asset=="TENSI.MDT";require(first_music && session.take_audio_commands().empty(),"Original entrance audio commands drain exactly once");
 auto tick=[&](){orb_cur_left=orb_prev_left=0;orb_cur_top=orb_prev_top=380;player_invincibility_time=20000;player_invincible=true;session.step({});};for(unsigned i=0;i<20;++i)tick();test_damage=true;tick();require(session.sariel_state().hp==17,"Live hook applies Sariel damage");player_is_hit=true;session.step({});require(session.state()==SessionState::playing && session.sariel_state().hp==17,"Normal miss preserves Sariel HP and state");unsigned deaths=native_extend_lives()+1;for(unsigned i=0;i<deaths;++i){orb_cur_left=orb_prev_left=0;orb_cur_top=orb_prev_top=380;player_is_hit=true;session.step({});}require(session.state()==SessionState::game_over,"Sariel life exhaustion enters Game Over");session.step({});require(session.state()==SessionState::playing && session.stage_number()==20 && session.sariel_state().hp==18 && session.sariel_state().phase==1 && score==0 && rem_bombs==1 && stage_timer==6000,"Continue reloads fresh Sariel and original resident/timer state");
 for(unsigned i=0;i<20;++i)tick();unsigned guard=0;while(session.sariel_state().hp>0){test_damage=true;tick();if(++guard>1000)throw std::runtime_error("First form damage stalled");}while(session.sariel_state().phase!=100){tick();if(++guard>2000)throw std::runtime_error("Second form transition stalled");}require(session.state()==SessionState::playing && session.sariel_state().hp==6,"Live phase99 transitions into six-HP second form");audio=session.take_audio_commands();bool second_music=false,transition_audio=false;for(auto a:audio){second_music|=a.operation=="bgm_load" && a.asset=="syugen.MDT";transition_audio|=a.operation=="se_transition";}require(second_music && transition_audio,"Live form transition lowers repeated SE and keeps original music command");for(unsigned i=0;i<20;++i)tick();while(session.sariel_state().hp>0){test_damage=true;tick();if(++guard>3000)throw std::runtime_error("Second form damage stalled");}auto before=score;while(!session.sariel_state().cleared){tick();if(++guard>4000)throw std::runtime_error("Final defeat stalled");}require(session.state()==SessionState::ending_pending && score==before+50000,"Final Sariel clear awards original bonus and hands off to ending boundary");auto cleared_score=score;checking_ending=true;session.step({});require(ending_fades>0,"Live ending uses original picture fade timings");require(session.state()==SessionState::title_pending && score==0,"Sariel ending, verdict and registration complete and clear resident score");require(scoredat_load()==0,"Ending score file reloads");bool stored_clear=false;for(unsigned place=0;place<10;++place)stored_clear|=scoredat_score[place]==cleared_score && scoredat_stages[place]==50 && scoredat_routes[place]==44682;scoredat_free();require(stored_clear,"Ending registration persists final score and cleared route");session.step({});require(session.state()==SessionState::title_pending && score==0,"Completed ending stays inert without replaying victory bonus");std::cout<<"Live Sariel start/miss/Continue, two forms, audio commands and ending handoff passed\n";
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
